  match r, ph with
  | 1, 0 => farm1_0_1RB1LD_0LC1RB_1LA0RB_1RB1LC
  | 1, 1 => farm1_1_1RB1LD_0LC1RB_1LA0RB_1RB1LC
  | 1, 2 => farm1_2_1RB1LD_0LC1RB_1LA0RB_1RB1LC
  | _, _ => farm1_0_1RB1LD_0LC1RB_1LA0RB_1RB1LC  (* unreachable: 0 < r < N0 + st *)
  end.

