  mkLRule (mkC StB (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S1] 1 0 [S1;S0]))
          (mkC StB (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S0] 1 0 [S1;S1])) 4 8.
Definition ch_iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA :
  check_arm tm true false rules iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA
            ch_iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LD_1LB0RC_1LA1RC_0LC0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA
  | _, _ => iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

