    { eapply arm_sound; [exact rules_sound_1RB1LD_1LB0RC_1LA1RC_0LC0LA | exact ok_iarm0_0_1RB1LD_1LB0RC_1LA1RC_0LC0LA]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

