(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LD_1LB0RC_1LA1RC_0LC0LA : NeverQuasiHaltsTr tm_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
Proof.
  apply (boardph_neverqhtr tm_1RB1LD_1LB0RC_1LA1RC_0LC0LA pins_1RB1LD_1LB0RC_1LA1RC_0LC0LA FAM 1
                           iarm_1RB1LD_1LB0RC_1LA1RC_0LC0LA 0 1
                           farm_1RB1LD_1LB0RC_1LA1RC_0LC0LA 1 1
                           fm1_1RB1LD_1LB0RC_1LA1RC_0LC0LA fm2_1RB1LD_1LB0RC_1LA1RC_0LC0LA 0 vis_1RB1LD_1LB0RC_1LA1RC_0LC0LA
                           [1;0;1] 0 34).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - lia.
  - exact iarm_sound_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact iarm_lhs_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact iarm_rhs_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact iarm_cb_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - lia.
  - lia.
  - exact farm_sound_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact farm_lhs_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact farm_rhs_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact farm_cb_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
  - exact vis_ok_1RB1LD_1LB0RC_1LA1RC_0LC0LA.
Qed.

End LDRT_1RB1LD_1LB0RC_1LA1RC_0LC0LA.

