Lemma farm_sound_1RB1RD_1RC0RA_1LD0LC_0RB1LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 -> RuleSound tm true true (farm_1RB1RD_1RC0RA_1LD0LC_0RB1LC r ph).
