    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1RC0RA_1LD0LC_0RB1LC | exact ok_farm1_1_1RB1RD_1RC0RA_1LD0LC_0RB1LC]. }
