Lemma vis_ok_1RB1RD_1RC0RA_1LD0LC_0RB1LC : forall r t, ~ In t pins_1RB1RD_1RC0RA_1LD0LC_0RB1LC -> 0 < r ->
  r < 1 + 1 ->
  srun_instr tm true true (vis_1RB1RD_1RC0RA_1LD0LC_0RB1LC r t) (lr_lhs (farm_1RB1RD_1RC0RA_1LD0LC_0RB1LC r 0))
    = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1RD_1RC0RA_1LD0LC_0RB1LC : NeverQuasiHaltsTr tm_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
Proof.
  apply (boardph_neverqhtr tm_1RB1RD_1RC0RA_1LD0LC_0RB1LC pins_1RB1RD_1RC0RA_1LD0LC_0RB1LC FAM 2
                           iarm_1RB1RD_1RC0RA_1LD0LC_0RB1LC 0 1
                           farm_1RB1RD_1RC0RA_1LD0LC_0RB1LC 1 1
                           fm1_1RB1RD_1RC0RA_1LD0LC_0RB1LC fm2_1RB1RD_1RC0RA_1LD0LC_0RB1LC 0 vis_1RB1RD_1RC0RA_1LD0LC_0RB1LC
                           [0;0;0] 0 20).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - lia.
  - exact iarm_sound_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact iarm_lhs_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact iarm_rhs_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact iarm_cb_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - lia.
  - lia.
  - exact farm_sound_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact farm_lhs_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact farm_rhs_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact farm_cb_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
  - exact vis_ok_1RB1RD_1RC0RA_1LD0LC_0RB1LC.
Qed.

